```js
const { Messages, Reactions } = require('../../database/dbcrudmethods');
const { user, MessageReaction } = require('../../database/db.cjs');

function formatpayload(row, senderRole, reactions = []) {
    return {
        id: row.id,
        text: row.content ?? row.text,
        timestamp: row.timestamp,
        senderId: row.senderId,
        senderRole: senderRole || null,
        reactions,
    };
}

async function reactionsForMessages(messageIds) {
    if (messageIds.length === 0) return {};
    const rows = await MessageReaction.findAll({ where: { messageId: messageIds } });
    const byMessage = {};
    for (const row of rows) {
        const mid = row.messageId;
        if (!byMessage[mid]) byMessage[mid] = {};
        const key = row.emoji;
        if (!byMessage[mid][key]) byMessage[mid][key] = [];
        byMessage[mid][key].push(row.userId);
    }
    const out = {};
    for (const mid of Object.keys(byMessage)) {
        out[mid] = Object.entries(byMessage[mid]).map(([emoji, userIds]) => ({ emoji, userIds }));
    }
    return out;
}
```

