const senders = await user.findAll({ where: { id: senderIds }, attributes: ['id', 'role'] });
const roleById = Object.fromEntries(senders.map((u) => [u.id, u.role]));
const reactions = await reactionsForMessages(history.map(m => m.id));
socket.emit('history', {
