@import "tailwindcss";

/* Base */
html,
body,
#root {
  min-height: 100%;
}

body {
  margin: 0;
  background: #f8fafc;
  color: #0f172a;
  -webkit-font-smoothing: antialiased;
}

* {
  box-sizing: border-box;
}

/* Icons */
.icon-xs { @apply !text-[14px]; }
.icon-sm { @apply !text-[16px]; }
.icon-md { @apply !text-[20px]; }
.icon-lg { @apply !text-[24px]; }

/* Layout */
.app-page {
  @apply flex min-h-screen flex-col bg-slate-50 pb-24;
}

.page-header {
  @apply sticky top-0 z-10 flex items-center justify-between gap-3 border-b border-slate-200/70 bg-white/90 px-4 py-4 backdrop-blur sm:px-6;
}

.page-header-title {
  @apply min-w-0 flex-1;
}

.page-title {
  @apply truncate text-lg font-semibold tracking-tight text-slate-900;
}

.page-subtitle {
  @apply mt-0.5 text-xs text-slate-500;
}

.page-content {
  @apply flex-1 space-y-4 px-4 pb-6 pt-4 sm:px-6;
}

.section-title {
  @apply text-xs font-semibold tracking-wide text-slate-400 uppercase;
}

/* Buttons */
.btn {
  @apply inline-flex cursor-pointer items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition-all duration-200 select-none active:scale-[0.97] disabled:pointer-events-none disabled:opacity-40;
}

.btn-primary {
  @apply bg-sky-600 text-white shadow-sm hover:bg-sky-700 hover:shadow-md;
}

.btn-secondary {
  @apply border border-slate-200 bg-white text-slate-700 shadow-sm hover:border-slate-300 hover:bg-slate-50;
}

.btn-ghost {
  @apply bg-slate-100 text-slate-600 hover:bg-slate-200;
}

.btn-danger {
  @apply bg-red-50 text-red-600 hover:bg-red-100;
}

.btn-success {
  @apply bg-emerald-600 text-white shadow-sm hover:bg-emerald-700 hover:shadow-md;
}

.btn-block {
  @apply w-full;
}

.btn-lg {
  @apply py-3.5;
}

.btn-sm {
  @apply px-3 py-1.5 text-xs;
}

.btn-icon {
  @apply flex h-9 w-9 shrink-0 cursor-pointer items-center justify-center rounded-lg text-slate-400 transition-colors hover:bg-slate-100 hover:text-sky-600 active:bg-slate-200;
}

.btn-icon-lg {
  @apply flex h-11 w-11 shrink-0 cursor-pointer items-center justify-center rounded-xl text-slate-400 transition-colors hover:bg-slate-100 hover:text-sky-600 active:bg-slate-200;
}

/* Inputs */
.input {
  @apply w-full rounded-xl border border-slate-200 bg-white px-3.5 py-2.5 text-sm text-slate-900 shadow-sm outline-none transition-all placeholder:text-slate-400 focus:border-sky-500 focus:ring-4 focus:ring-sky-100;
}

.select {
  @apply w-full cursor-pointer rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm text-slate-900 shadow-sm outline-none transition-all focus:border-sky-500 focus:ring-4 focus:ring-sky-100;
}

label.field {
  @apply flex flex-col gap-1.5 text-sm font-medium text-slate-700;
}

.search-box {
  @apply flex items-center gap-2 rounded-xl border border-slate-200 bg-slate-50 px-3.5 py-2.5 shadow-sm transition focus-within:border-sky-500 focus-within:bg-white focus-within:ring-4 focus-within:ring-sky-100;
}

.search-input {
  @apply flex-1 bg-transparent text-sm text-slate-900 outline-none placeholder:text-slate-400;
}

.search-clear {
  @apply flex h-7 w-7 shrink-0 cursor-pointer items-center justify-center rounded-full text-slate-400 transition-colors hover:bg-slate-200 hover:text-slate-600;
}

/* Cards & rows */
.card {
  @apply overflow-hidden rounded-2xl border border-slate-200/80 bg-white shadow-sm;
}

.card-pad {
  @apply rounded-2xl border border-slate-200/80 bg-white p-5 shadow-sm;
}

.card-divide {
  @apply divide-y divide-slate-100;
}

.row {
  @apply flex items-center justify-between gap-3 px-4 py-3;
}

.row-btn {
  @apply w-full cursor-pointer text-left transition-colors hover:bg-slate-50 active:bg-slate-100;
}

.row-primary {
  @apply flex items-center justify-between gap-3 px-4 py-3;
}

.row-primary + .row-primary {
  @apply border-t border-slate-100;
}

/* Avatars */
.avatar {
  @apply flex h-10 w-10 shrink-0 items-center justify-center rounded-full text-sm font-semibold;
}

.avatar-sm {
  @apply h-8 w-8 text-xs;
}

.avatar-lg {
  @apply h-16 w-16 text-xl font-bold;
}

.avatar-present {
  @apply bg-emerald-100 text-emerald-700;
}

.avatar-missing {
  @apply bg-amber-100 text-amber-700;
}

.avatar-neutral {
  @apply bg-sky-100 text-sky-700;
}

.avatar-soft {
  @apply bg-slate-100 text-slate-500;
}

/* Pills */
.pill {
  @apply inline-flex shrink-0 items-center gap-1 rounded-full px-2.5 py-0.5 text-[11px] font-semibold;
}

.pill-present {
  @apply bg-emerald-50 text-emerald-700;
}

.pill-missing {
  @apply bg-amber-50 text-amber-700;
}

.pill-pending {
  @apply bg-sky-100 text-sky-700;
}

.pill-ready {
  @apply bg-emerald-50 text-emerald-700;
}

.pill-info {
  @apply bg-slate-100 text-slate-600;
}

.pill-warn {
  @apply bg-red-50 text-red-600;
}

/* Filters */
.filter-chip {
  @apply cursor-pointer rounded-full border border-slate-200 bg-white px-4 py-1.5 text-xs font-medium text-slate-600 shadow-sm transition-all hover:border-slate-300 hover:bg-slate-50 active:scale-95;
}

.filter-chip-active {
  @apply border-sky-500 bg-sky-50 text-sky-700;
}

/* Segmented control */
.segmented {
  @apply flex rounded-full bg-slate-100 p-0.5;
}

.segmented-btn {
  @apply flex-1 cursor-pointer rounded-full px-4 py-1.5 text-xs font-semibold text-slate-500 transition-all hover:text-slate-700;
}

.segmented-btn-active {
  @apply bg-white text-slate-800 shadow-sm;
}

/* Progress */
.progress {
  @apply h-2 overflow-hidden rounded-full bg-slate-100;
}

.progress-bar {
  @apply h-full rounded-full bg-emerald-500 transition-all duration-500;
}

/* Empty state */
.empty-state {
  @apply flex flex-col items-center justify-center gap-2 px-6 py-16 text-center;
}

.empty-icon {
  @apply flex h-14 w-14 items-center justify-center rounded-full bg-slate-100 text-slate-400;
}

.empty-title {
  @apply text-sm font-semibold text-slate-700;
}

.empty-text {
  @apply max-w-xs text-xs text-slate-400;
}

/* Spinner */
.spinner {
  @apply h-8 w-8 animate-spin rounded-full border-2 border-sky-600 border-t-transparent;
}

/* Banners */
.error-banner {
  @apply mx-4 flex items-center justify-between gap-2 rounded-xl border border-red-200 bg-red-50 px-4 py-2.5 text-sm text-red-600 sm:mx-6;
}

.success-banner {
  @apply mx-4 flex items-center justify-between gap-2 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-2.5 text-sm text-emerald-700 sm:mx-6;
}

/* Bottom sheet */
.sheet-backdrop {
  @apply fixed inset-0 z-30 flex items-end justify-center bg-slate-900/40 backdrop-blur-sm;
  animation: fade-in 0.2s ease-out;
}

.sheet {
  @apply flex max-h-[85vh] w-full max-w-lg flex-col rounded-t-3xl bg-white shadow-2xl;
  animation: slide-up 0.25s ease-out;
}

.sheet-handle {
  @apply mx-auto mt-3 h-1 w-10 shrink-0 rounded-full bg-slate-200;
}

.sheet-body {
  @apply flex-1 space-y-4 overflow-y-auto px-5 py-4;
}

.sheet-footer {
  @apply flex shrink-0 gap-3 border-t border-slate-100 px-5 py-3;
}

.sheet-hero {
  @apply flex flex-col items-center gap-2 px-5 pt-2 pb-4;
}

.sheet-title {
  @apply text-lg font-semibold text-slate-900;
}

.sheet-sub {
  @apply text-xs text-slate-500;
}

/* Modal */
.modal-backdrop {
  @apply fixed inset-0 z-40 flex items-end justify-center bg-slate-900/40 backdrop-blur-sm sm:items-center sm:p-4;
  animation: fade-in 0.2s ease-out;
}

.modal {
  @apply flex max-h-[85vh] w-full max-w-lg flex-col overflow-hidden rounded-t-3xl bg-white shadow-2xl sm:rounded-2xl;
  animation: slide-up 0.25s ease-out;
}

.modal-header {
  @apply flex shrink-0 items-center justify-between gap-3 border-b border-slate-100 px-4 py-3;
}

.modal-title {
  @apply min-w-0 flex-1 truncate text-sm font-semibold text-slate-800;
}

.modal-body {
  @apply flex-1 overflow-y-auto px-4 py-3;
}

.modal-footer {
  @apply flex shrink-0 gap-2 border-t border-slate-100 px-4 py-3;
}

/* Checkbox rows */
.check-row {
  @apply flex cursor-pointer items-center gap-3 rounded-xl px-3 py-2.5 transition-colors hover:bg-slate-50;
}

.check-row-checked {
  @apply bg-sky-50 hover:bg-sky-50;
}

.checkbox {
  @apply h-4 w-4 shrink-0 cursor-pointer accent-sky-600;
}

/* Keyframes */
@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes slide-up {
  from { transform: translateY(100%); }
  to { transform: translateY(0); }
}

@keyframes slide-down {
  from { transform: translateY(-100%); }
  to { transform: translateY(0); }
}

/* Connectivity */
.conn-bar {
  @apply fixed top-0 right-0 left-0 z-50 flex items-center justify-center gap-2 px-4 py-1.5 text-xs font-medium backdrop-blur;
  animation: slide-down 0.2s ease-out;
}

.conn-bar-syncing {
  @apply bg-sky-600/90 text-white;
}

.conn-bar-offline {
  @apply border-b border-amber-200/60 bg-amber-50/90 text-amber-700;
}

.conn-dot {
  @apply h-1.5 w-1.5 rounded-full bg-current;
  animation: pulse 1.2s ease-in-out infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}

/* Bottom nav */
.bottom-nav {
  @apply fixed right-0 bottom-0 left-0 z-20;
}

.bottom-nav-content {
  @apply flex border-t border-slate-200/80 bg-white/95 backdrop-blur;
  padding-bottom: env(safe-area-inset-bottom);
}

.bottom-nav-action {
  @apply flex min-w-0 flex-1 cursor-pointer flex-col items-center justify-center gap-0.5 py-2.5 text-[10px] font-medium text-slate-400 transition-colors;
}

.bottom-nav-action-active {
  @apply text-sky-600;
}

.bottom-nav-icon {
  @apply relative flex items-center justify-center;
}

.bottom-nav-action-active .bottom-nav-icon::after {
  content: "";
  @apply absolute -bottom-1.5 h-1 w-1 rounded-full bg-sky-600;
}

.bottom-nav-action:hover {
  @apply text-slate-600;
}

.bottom-nav-pending {
  @apply absolute -top-0.5 -right-1.5 flex h-4 min-w-4 items-center justify-center rounded-full bg-amber-500 px-1 text-[9px] font-bold text-white;
}

/* Chat */
.chat-page {
  @apply flex min-h-screen flex-col bg-slate-100 pb-14;
}

.chat-header {
  @apply sticky top-0 z-10 flex items-center justify-between gap-3 border-b border-slate-200/70 bg-white/90 px-4 py-4 backdrop-blur sm:px-6;
}

.chat-title {
  @apply text-lg font-semibold tracking-tight text-slate-900;
}

.chat-offline-pill {
  @apply flex items-center gap-1.5 rounded-full bg-amber-50 px-3 py-1 text-xs font-medium text-amber-700;
}

.chat-online-pill {
  @apply flex items-center gap-1.5 rounded-full bg-emerald-50 px-3 py-1 text-xs font-medium text-emerald-700;
}

.chat-layout {
