}

.chat-scroll {
  @apply flex-1 overflow-y-auto px-3 py-5 sm:px-5 lg:px-6;
}

.chat-message-list {
  @apply w-full space-y-3;
}

.chat-empty {
  @apply flex min-h-[calc(100vh-250px)] items-center justify-center text-center;
}

.chat-empty-text {
  @apply text-base font-medium text-slate-500;
}

.chat-composer-shell {
  @apply sticky bottom-14 border-t border-slate-200/80 bg-white;
}

.chat-content {
  @apply w-full;
}

.chat-input-form {
  @apply border-t border-slate-200/80 bg-white px-3 py-3 sm:px-4;
}

.chat-input-box {
