}

.chat-send-button {
  @apply !h-10 !w-10 !bg-sky-600 !text-white transition-colors duration-150;
}

.chat-send-button:hover {
  @apply !bg-sky-700;
}

.chat-send-button.Mui-disabled {
  @apply !bg-slate-200 !text-slate-400;
}

.chat-bubble-row {
  @apply flex w-full items-start gap-2;
}

.chat-bubble-row-own {
  @apply justify-end;
}

.chat-bubble-row-other {
  @apply justify-start;
}

.chat-bubble {
  @apply rounded-2xl px-4 py-2 text-sm leading-6 shadow-sm;
}

.chat-bubble-own {
  @apply rounded-br-md bg-sky-600 text-white;
}

.chat-bubble-other {
  @apply rounded-bl-md border border-slate-200 bg-white text-slate-800;
}

.chat-bubble-admin {
  @apply border-amber-300 bg-amber-50 text-slate-900 ring-1 ring-amber-300;
}

.chat-bubble-text {
  @apply whitespace-pre-wrap break-words;
}

.chat-bubble-time {
  @apply mt-1 text-[11px];
}

.chat-bubble-time-own {
  @apply text-sky-100;
}

.chat-bubble-time-other {
  @apply text-slate-400;
}

.chat-bubble-time-admin {
  @apply text-amber-700;
}

.chat-bubble-container {
  @apply relative flex w-fit max-w-[78%] flex-col;
}

.chat-reaction-bar {
  @apply absolute -top-9 z-10 flex items-center gap-0.5 rounded-full border border-slate-200 bg-white px-1.5 py-1 shadow-lg;
}

.chat-bubble-row-own .chat-reaction-bar {
  @apply right-0;
}

.chat-bubble-row-other .chat-reaction-bar {
  @apply left-0;
}

.chat-reaction-option {
  @apply h-8 w-8 cursor-pointer rounded-full text-xl leading-none transition-transform duration-150 hover:scale-125;
}

.chat-reaction-option:hover {
  @apply bg-slate-100;
}

.chat-reactions {
