}

.chat-bubble-row-own .chat-reactions {
  @apply justify-end;
}

.chat-reaction {
  @apply flex cursor-pointer items-center gap-1 rounded-full border border-slate-200 bg-white px-2 py-0.5 text-xs font-medium text-slate-600 shadow-sm transition-colors;
}

.chat-reaction-mine {
  @apply border-sky-400 bg-sky-50 text-sky-700;
}

.chat-avatar {
  @apply flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-sky-100 text-sky-700 text-sm font-semibold;
}

/* Dashboard */
.dashboard-page {
  @apply flex min-h-screen flex-col bg-slate-50 pb-24;
}

.dashboard-header {
  @apply sticky top-0 z-10 border-b border-slate-200/70 bg-white/90 px-4 pt-4 pb-3 backdrop-blur sm:px-6;
}

.dashboard-header-inner {
  @apply flex flex-col gap-1;
}

.dashboard-programme-btn {
