}

.dashboard-section-heading {
  @apply flex items-center gap-2 text-xs font-semibold tracking-wide text-slate-400 uppercase;
}

.dashboard-section-heading-missing {
  @apply text-amber-600;
}

.dashboard-section-heading-present {
  @apply text-emerald-600;
}

.dashboard-route-card {
  @apply cursor-pointer rounded-2xl border border-slate-200/80 bg-white px-4 py-3.5 shadow-sm transition-all hover:-translate-y-px hover:border-sky-300 hover:shadow-md active:scale-[0.99];
}

.dashboard-route-card-selected {
  @apply border-sky-400 ring-2 ring-sky-100;
}

.dashboard-route-top {
  @apply mb-2 flex items-start justify-between gap-2;
}

.dashboard-route-name {
  @apply min-w-0 truncate text-sm font-medium text-slate-800;
}

.dashboard-route-stats {
  @apply mt-1.5 flex justify-between gap-2;
}

.dashboard-route-count {
  @apply truncate text-xs text-emerald-600;
}

.dashboard-route-missing {
  @apply shrink-0 text-xs font-medium text-amber-600;
}

.dashboard-ready-shell {
  @apply fixed right-0 bottom-16 left-0 z-30 px-4 sm:px-6;
}

.dashboard-ready-btn {
  @apply flex w-full cursor-pointer items-center justify-center gap-2 rounded-2xl border-2 border-dashed border-slate-300 bg-white/95 py-3.5 text-sm font-semibold text-slate-500 shadow-lg backdrop-blur transition-all hover:border-sky-400 hover:text-sky-600 active:scale-[0.98];
}

.dashboard-ready-btn-on {
  @apply border-emerald-300 bg-emerald-50/95 text-emerald-700 hover:border-emerald-400 hover:text-emerald-700;
