/* Directory */
.directory-page {
  @apply flex min-h-screen flex-col bg-slate-50 pb-24;
}

.directory-header {
  @apply sticky top-0 z-10 flex items-center justify-between gap-3 border-b border-slate-200/70 bg-white/90 px-4 pt-4 pb-3 backdrop-blur sm:px-6;
}

.directory-title {
  @apply text-lg font-semibold tracking-tight text-slate-900;
}

.directory-subhead {
  @apply flex min-w-0 flex-1 items-center gap-3;
}

.directory-missing-pill {
  @apply shrink-0 rounded-full bg-amber-100 px-3 py-1 text-xs font-semibold text-amber-700;
}

.directory-search-shell {
  @apply space-y-3 bg-white px-4 pt-3 pb-1 sm:px-6;
}

.directory-filters {
  @apply flex gap-2 bg-white px-4 pb-4 sm:px-6;
}

.directory-list-shell {
