}

.directory-avatar {
  @apply flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-sm font-semibold;
}

.directory-avatar-present {
  @apply bg-emerald-100 text-emerald-700;
}

.directory-avatar-missing {
  @apply bg-amber-100 text-amber-700;
}

.directory-row {
  @apply flex items-center justify-between gap-3 px-4 py-3;
}

.directory-row-left {
  @apply flex min-w-0 flex-1 items-center gap-3;
}

.directory-row-text {
  @apply flex min-w-0 flex-col;
}

.directory-row-name {
  @apply truncate text-sm font-medium text-slate-800;
}

.directory-row-status {
  @apply truncate text-xs text-slate-500;
}

.directory-status-present {
  @apply text-emerald-600;
}

.directory-status-missing {
  @apply font-medium text-amber-600;
}

.directory-row-actions {
  @apply flex shrink-0 items-center gap-2;
}

.directory-action-btn {
  @apply flex cursor-pointer items-center gap-1 rounded-full px-3 py-2 text-xs font-semibold transition-colors;
}

.directory-action-check {
  @apply bg-sky-50 text-sky-700 hover:bg-sky-100;
}

.directory-action-undo {
