}

/* Profile sheet (dashboard/directory) */
.profile-backdrop {
  @apply fixed inset-0 z-30 flex items-end justify-center bg-slate-900/40 backdrop-blur-sm;
  animation: fade-in 0.2s ease-out;
}

.profile-sheet {
  @apply flex w-full max-w-lg flex-col gap-4 rounded-t-3xl bg-white px-5 pb-8 pt-1 shadow-2xl;
  animation: slide-up 0.25s ease-out;
}

.profile-handle {
  @apply mx-auto h-1 w-10 rounded-full bg-slate-200;
}

.profile-hero {
  @apply flex flex-col items-center gap-2 pt-2 pb-1;
}

.profile-hero-avatar {
  @apply flex h-16 w-16 items-center justify-center rounded-full text-xl font-bold;
}

.profile-hero-avatar-present {
  @apply bg-emerald-100 text-emerald-700;
}

.profile-hero-avatar-missing {
