}

.profile-hero-status-missing {
  @apply bg-amber-50 text-amber-700;
}

.profile-details {
  @apply flex flex-col divide-y divide-slate-100 overflow-hidden rounded-2xl bg-slate-50;
}

.profile-detail-row {
  @apply flex items-center gap-3 px-4 py-3;
}

.profile-detail-icon {
  @apply shrink-0 text-slate-400;
}

.profile-detail-label {
  @apply shrink-0 text-sm font-medium text-slate-500;
}

.profile-detail-value {
  @apply ml-auto text-right text-sm text-slate-800;
}

.profile-detail-value-note {
  @apply font-medium text-amber-600;
}

.profile-actions {
  @apply flex gap-3 pt-1;
}

.profile-action-btn {
  @apply flex flex-1 cursor-pointer items-center justify-center gap-2 rounded-2xl py-3.5 text-sm font-semibold transition-all active:scale-[0.98];
}

.profile-action-present {
  @apply bg-sky-600 text-white shadow-sm hover:bg-sky-700;
}

.profile-action-absent {
