}

.staff-action-row {
  @apply flex w-full cursor-pointer items-center gap-3 rounded-2xl border border-slate-200/80 bg-white px-4 py-3.5 text-left shadow-sm transition-all hover:-translate-y-px hover:border-slate-300 hover:shadow-md active:scale-[0.99];
}

.staff-action-icon {
