/* Camera page */
.camera-page {
  @apply flex min-h-screen flex-col bg-slate-950 pb-24;
}

.camera-header {
  @apply sticky top-0 z-10 flex items-center justify-between gap-3 bg-slate-950/80 px-4 py-4 backdrop-blur sm:px-6;
}

.camera-title {
  @apply text-lg font-semibold tracking-tight text-white;
