/* Programme management */
.pgm-route-row {
  @apply flex items-center gap-2 rounded-xl border border-slate-200/80 bg-white px-3 py-2.5;
}

.pgm-delegate-row {
  @apply flex items-center justify-between rounded-xl border border-slate-200/80 bg-white px-4 py-3;
}

.pgm-tab-note {
