import ChatIcon from '@mui/icons-material/Chat';
import DashboardIcon from '@mui/icons-material/Dashboard';
import CameraAlt from '@mui/icons-material/CameraAlt';
import AccountCircle from '@mui/icons-material/AccountCircle';
import QrCode from '@mui/icons-material/QrCode';
import { useConnectivity } from '../../hooks/useConnectivity';

function getAuthUser() {
    const raw = localStorage.getItem('authUser');
    if (!raw) return null;
    try {
        return JSON.parse(raw);
    } catch {
        return null;
    }
}

export default function FixedBottomNavigation() {
    const { pathname } = useLocation();
    const currentUser = getAuthUser();
    const isStaff = currentUser?.role === 'staff';
    const { isOnline, pendingCount } = useConnectivity();

    const items = [
        { key: 'chat', label: 'Chat', to: '/chat', icon: <ChatIcon className="icon-md" />, show: true },
        { key: 'dashboard', label: 'Dashboard', to: '/dashboard', icon: <DashboardIcon className="icon-md" />, show: isStaff },
        { key: 'camera', label: 'Camera', to: '/camera', icon: <CameraAlt className="icon-md" />, show: isStaff },
        { key: 'badge', label: 'Badge', to: '/badge', icon: <QrCode className="icon-md" />, show: !isStaff },
        { key: 'profile', label: 'Profile', to: '/profile', icon: <AccountCircle className="icon-md" />, show: true },
    ];

    return (
        <nav className="bottom-nav">
            <div className="bottom-nav-content">
                {items.filter((i) => i.show).map((item) => {
                    const active = pathname.startsWith(item.to);
                    const isChat = item.key === 'chat';
                    return (
                        <Link
                            key={item.key}
                            to={item.to}
                            className={`bottom-nav-action ${active ? 'bottom-nav-action-active' : ''}`}
                        >
                            <span className="bottom-nav-icon">
                                {item.icon}
                                {!isOnline && isChat && pendingCount > 0 && (
                                    <span className="bottom-nav-pending">{pendingCount}</span>
                                )}
                            </span>
                            <span>{isChat && !isOnline ? 'Chat' : item.label}</span>
                        </Link>
                    );
                })}
            </div>
        </nav>
    );
}

import { useConnectivity } from '../../hooks/useConnectivity';

export default function ConnectivityIndicator() {
  const { isOnline, isSyncing, pendingCount } = useConnectivity();

  if (isSyncing) {
    return (
      <div className="conn-bar conn-bar-syncing">
        <span className="conn-dot" />
        Syncing…
      </div>
    );
  }

  if (!isOnline) {
    return (
      <div className="conn-bar conn-bar-offline">
        <svg className="h-3.5 w-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <line x1="1" y1="1" x2="23" y2="23" />
          <path d="M16.72 11.06A10.94 10.94 0 0 1 19 12.55" />
          <path d="M5 12.55a10.94 10.94 0 0 1 5.17-2.39" />
          <path d="M10.71 5.05A16 16 0 0 1 22.56 9" />
          <path d="M1.42 9a15.91 15.91 0 0 1 4.7-2.88" />
          <path d="M8.53 16.11a6 6 0 0 1 6.95 0" />
          <line x1="12" y1="20" x2="12.01" y2="20" />
        </svg>
        Offline{pendingCount > 0 ? ` · ${pendingCount} pending` : ''}
      </div>
    );
  }

  return null;
}

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { authLogin } from '../../services/api.js';
import LoginRoundedIcon from '@mui/icons-material/LoginRounded';

export default function Login() {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = async (event) => {
    event.preventDefault();
    setError('');
    try {
      const data = await authLogin({ email, password });
      localStorage.setItem('authUser', JSON.stringify(data));
      navigate('/');
    } catch (err) {
      setError(err.message || 'Unable to login');
    }
  };

  return (
    <main className="auth-page">
      <section className="auth-card">
        <div className="auth-logo">
          <div className="auth-logo-mark">
            <LoginRoundedIcon className="icon-lg" />
          </div>
          <div>
            <h1 className="auth-title">Welcome back</h1>
            <p className="auth-subtitle">Sign in to continue</p>
          </div>
        </div>
        <form onSubmit={handleSubmit} className="auth-form">
          <label className="field">
            Email
            <input
              className="input"
              type="email"
              value={email}
              onChange={(event) => setEmail(event.target.value)}
              required
            />
          </label>
          <label className="field">
            Password
            <input
              className="input"
              type="password"
              value={password}
              onChange={(event) => setPassword(event.target.value)}
              required
            />
          </label>
          {error && <p className="auth-error-text">{error}</p>}
          <button className="btn btn-primary btn-block btn-lg" type="submit">Login</button>
        </form>
      </section>
    </main>
  );
}

import { Link } from 'react-router-dom';
import RemoveRedEyeRoundedIcon from '@mui/icons-material/RemoveRedEyeRounded';

export default function Onboarding() {
  return (
    <main className="auth-page">
      <section className="auth-card">
        <div className="auth-logo">
          <div className="auth-logo-mark">
            <RemoveRedEyeRoundedIcon className="icon-lg" />
          </div>
          <div>
            <h1 className="auth-title">OpenGlimpse</h1>
            <p className="auth-subtitle">Facial recognition attendance for your delegations.</p>
          </div>
        </div>
        <Link className="btn btn-primary btn-block btn-lg" to="/login">Login</Link>
      </section>
    </main>
  );
}

