@import "tailwindcss";

/* ============================================================
   Design tokens
   ============================================================ */
:root {
  --bg: #0b0d10;
  --surface: #171a1f;
  --surface-2: #1e232b;
  --accent: #3b82f6;
  --accent-deep: #2563eb;
  --ink: #f5f7fa;
  --muted: #8b93a1;
  --edge: rgba(255, 255, 255, 0.06);
  --ok: #34d399;
  --bad: #f87171;
  --warn: #fbbf24;
  --ok-dim: rgba(52, 211, 153, 0.12);
  --bad-dim: rgba(248, 113, 113, 0.12);
  --warn-dim: rgba(251, 191, 36, 0.12);
}

@theme {
  --color-bg: var(--bg);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-accent: var(--accent);
  --color-accent-deep: var(--accent-deep);
  --color-ink: var(--ink);
  --color-muted: var(--muted);
  --color-edge: var(--edge);
  --color-ok: var(--ok);
  --color-bad: var(--bad);
  --color-warn: var(--warn);
  --color-ok-dim: var(--ok-dim);
  --color-bad-dim: var(--bad-dim);
  --color-warn-dim: var(--warn-dim);
  --font-sans: "Manrope", ui-sans-serif, system-ui, sans-serif;
}

@theme inline {
  --shadow-glow: 0 8px 24px -8px rgba(59, 130, 246, 0.45);
}

/* ============================================================
   Base
   ============================================================ */
html,
body,
#root {
  min-height: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

* {
  box-sizing: border-box;
}

::selection {
  background: rgba(59, 130, 246, 0.35);
}

/* Prevent iOS auto-zoom on focus */
.input,
.select,
.textarea,
.search-input,
input[type="date"],
input[type="email"],
input[type="password"],
input[type="url"],
input[type="file"],
textarea {
  font-size: 16px;
}

/* ============================================================
   Typography
   ============================================================ */
.display {
  @apply text-[26px] font-extrabold tracking-tight text-ink;
}

.page-title {
  @apply text-lg font-bold tracking-tight text-ink;
}

.title {
  @apply text-base font-bold text-ink;
