import { Link, useLocation } from "react-router-dom";
import ChatBubbleOutline from "@mui/icons-material/ChatBubbleOutline";
import ChatBubble from "@mui/icons-material/ChatBubble";
import DashboardOutlined from "@mui/icons-material/DashboardOutlined";
import DashboardIcon from "@mui/icons-material/Dashboard";
import CameraAltOutlined from "@mui/icons-material/CameraAltOutlined";
import CameraAltIcon from "@mui/icons-material/CameraAlt";
import QrCode2Outlined from "@mui/icons-material/QrCode2Outlined";
import QrCode2 from "@mui/icons-material/QrCode2";
import AccountCircleOutlined from "@mui/icons-material/AccountCircleOutlined";
import AccountCircle from "@mui/icons-material/AccountCircle";
import { useConnectivity } from "../../hooks/useConnectivity";

function getAuthUser() {
    const raw = localStorage.getItem('authUser');
    if (!raw) return null;
    try {
        return JSON.parse(raw);
    } catch {
        return null;
    }
}

function NavItem({ to, label, isActive, offline, icon: Icon, iconActive: IconActive }) {
    return (
        <Link
            to={to}
            className={`nav-item ${isActive ? "nav-item-active" : ""}`}
            aria-label={label}
        >
            <span className="relative nav-icon-wrap">
                {isActive ? <IconActive /> : <Icon />}
                {offline && (
                    <span className="absolute -top-0.5 -right-0.5 h-2 w-2 rounded-full bg-warn" />
                )}
            </span>
            <span>{label}</span>
        </Link>
    );
}

export default function BottomNav() {
    const { pathname } = useLocation();
    const currentUser = getAuthUser();
    const { isOnline } = useConnectivity();
    const isStaff = currentUser?.role === 'staff';

    const tabs = [];
    tabs.push({
        to: "/chat",
        label: "Chat",
        icon: ChatBubbleOutline,
        iconActive: ChatBubble,
        isActive: pathname === "/chat",
        offline: !isOnline,
    });
    if (isStaff) {
        tabs.push({
            to: "/dashboard",
            label: "Dashboard",
            icon: DashboardOutlined,
            iconActive: DashboardIcon,
            isActive: pathname === "/dashboard" || pathname.startsWith("/dashboard/routes"),
        });
        tabs.push({
            to: "/camera",
            label: "Camera",
            icon: CameraAltOutlined,
            iconActive: CameraAltIcon,
            isActive: pathname === "/camera",
        });
    } else {
        tabs.push({
            to: "/badge",
            label: "Badge",
            icon: QrCode2Outlined,
            iconActive: QrCode2,
            isActive: pathname === "/badge",
        });
    }
    tabs.push({
        to: "/profile",
        label: "Profile",
        icon: AccountCircleOutlined,
        iconActive: AccountCircle,
        isActive: pathname === "/profile",
    });

    return (
        <nav className="nav-pill" aria-label="Primary">
            {tabs.map((tab) => (
                <NavItem key={tab.to} {...tab} />
            ))}
        </nav>
    );
}

import { useConnectivity } from '../../hooks/useConnectivity';

export default function ConnectivityIndicator() {
  const { isOnline, isSyncing } = useConnectivity();

  if (isSyncing) {
    return (
      <div className="conn-bar conn-bar-syncing" role="status">
        <span className="conn-dot" />
        <p>Syncing...</p>
      </div>
    );
  }

  if (!isOnline) {
    return (
      <div className="conn-bar conn-bar-offline" role="status">
        <span className="conn-dot" />
        <p>Offline</p>
      </div>
    );
  }

  return null;
}

import ReportProblemRounded from "@mui/icons-material/ReportProblemRounded";

export default function ConfirmDialog({
    open,
    title,
    message,
    confirmLabel = "Delete",
    danger = true,
    busy = false,
    onConfirm,
    onCancel,
}) {
    if (!open) return null;

    return (
        <div className="confirm-backdrop" onClick={busy ? undefined : onCancel}>
            <div className="confirm-card" role="dialog" aria-modal="true" onClick={(e) => e.stopPropagation()}>
                <div className="confirm-icon">
                    <ReportProblemRounded />
                </div>
                <div>
                    <h3 className="confirm-title">{title}</h3>
                    <p className="confirm-text">{message}</p>
                </div>
                <div className="confirm-actions">
                    <button className="btn btn-secondary flex-1" onClick={onCancel} disabled={busy}>
                        Cancel
                    </button>
                    <button
                        className={`btn flex-1 ${danger ? "btn-danger-solid" : "btn-primary"}`}
                        onClick={onConfirm}
                        disabled={busy}
                    >
                        {busy ? "Please wait..." : confirmLabel}
                    </button>
                </div>
            </div>
        </div>
    );
}

export default function EmptyState({ icon, title, desc, action }) {
    return (
        <div className="empty-state">
            {icon && <div className="empty-icon">{icon}</div>}
            <div>
                <p className="empty-title">{title}</p>
                {desc && <p className="empty-desc">{desc}</p>}
            </div>
            {action && <div className="empty-action">{action}</div>}
        </div>
    );
}

