// Node loader hook to run Vite client source in Node tests.
// Resolves extensionless relative imports and replaces the Vite-only
// `import.meta.env.VITE_API_URL` expression before evaluation.
const { registerHooks } = require('node:module');
const path = require('node:path');

process.env.TEST_API_BASE ||= '';

registerHooks({
  resolve(specifier, context, nextResolve) {
    if (
      context.parentURL &&
      (specifier.startsWith('./') || specifier.startsWith('../')) &&
      path.extname(specifier) === ''
    ) {
      return nextResolve(specifier + '.js', context);
    }
    return nextResolve(specifier, context);
  },
  load(url, context, nextLoad) {
    const result = nextLoad(url, context);
    if (url.includes('/src/client/src/')) {
      const patched = result.source
        .toString()
        .replaceAll("import.meta.env.VITE_API_URL || ''", "process.env.TEST_API_BASE || ''");
      return { ...result, source: patched };
    }
    return result;
  },
});

import 'fake-indexeddb/auto';
import { test, beforeEach } from 'node:test';
import assert from 'node:assert/strict';

import { db } from '../../src/db/localDB.js';
import * as api from '../../src/services/api.js';
import { changeHandler } from '../../src/sync/syncEngine.js';

// browser-like globals
let online = true;
Object.defineProperty(globalThis, 'navigator', { configurable: true, get: () => ({ onLine: online }) });

function makeStorage() {
  const store = new Map();
  return {
    getItem: (k) => (store.has(k) ? store.get(k) : null),
    setItem: (k, v) => void store.set(k, String(v)),
    removeItem: (k) => void store.delete(k),
    clear: () => store.clear(),
  };
}
Object.defineProperty(globalThis, 'localStorage', { configurable: true, value: makeStorage() });

let fetchHandler = null;
const fetchCalls = [];
globalThis.fetch = async (url, init = {}) => {
  fetchCalls.push({ url, init });
  if (fetchHandler) return fetchHandler(url, init);
  return jsonResponse({ error: 'unhandled request' }, 404);
};

function jsonResponse(data, status = 200) {
  return { ok: status >= 200 && status < 300, status, text: async () => JSON.stringify(data) };
}
function setOnline(value) {
  online = value;
}
function setFetch(handler) {
  fetchHandler = handler;
}
function authUser(user) {
  localStorage.setItem('authUser', JSON.stringify(user));
}

beforeEach(async () => {
  await db.requestCache.clear();
  await db.pendingChanges.clear();
  localStorage.clear();
  online = true;
  fetchHandler = null;
  fetchCalls.length = 0;
});

// ── api.js: GET caching ──────────────────────────────────────

test('online GET on a synced path caches the response', async () => {
  setFetch(() => jsonResponse([{ id: 1, name: 'P1' }]));
  const data = await api.getProgrammes();
  assert.deepEqual(data, [{ id: 1, name: 'P1' }]);
  const cached = await db.requestCache.get('/programmes');
  assert.deepEqual(cached.data, [{ id: 1, name: 'P1' }]);
});

test('online GET 204 returns null and is not cached', async () => {
  setFetch(() => ({ ok: true, status: 204, text: async () => '' }));
  const data = await api.getProgrammes();
  assert.equal(data, null);
  assert.equal(await db.requestCache.get('/programmes'), undefined);
});

test('GET with query string caches by base path only', async () => {
  setFetch(() => jsonResponse([{ id: 7, name: 'Bus A' }]));
  await api.getRoutes(1, true);
  const cached = await db.requestCache.get('/programmes/1/routes');
  assert.ok(cached);
  assert.equal(await db.requestCache.get('/programmes/1/routes?archived=true'), undefined);
});

test('online GET failure on a synced path falls back to cache', async () => {
  await db.requestCache.put({ path: '/programmes', data: [{ id: 1, name: 'cached' }] });
  setFetch(() => jsonResponse({ error: 'boom' }, 500));
  const data = await api.getProgrammes();
  assert.deepEqual(data, [{ id: 1, name: 'cached' }]);
});

test('online GET failure without cache rejects with offline error', async () => {
  setFetch(() => jsonResponse({ error: 'boom' }, 500));
  await assert.rejects(api.getProgrammes(), /Not available offline/);
});

test('offline GET serves from cache', async () => {
  await db.requestCache.put({ path: '/programmes', data: [{ id: 2, name: 'P2' }] });
  setOnline(false);
  const data = await api.getProgrammes();
  assert.deepEqual(data, [{ id: 2, name: 'P2' }]);
  assert.equal(fetchCalls.length, 0);
});

test('offline GET without cache rejects', async () => {
  setOnline(false);
  await assert.rejects(api.getProgrammes(), /Not available offline/);
});

// ── api.js: offline writes ───────────────────────────────────

test('offline POST queues the op and returns optimistic result', async () => {
  setOnline(false);
  const result = await api.createProgramme({ name: 'Offline Prog' });
  assert.deepEqual(result, { name: 'Offline Prog', id: 'pending' });
  const pc = await db.pendingChanges.get('current');
  assert.equal(pc.ops.length, 1);
  assert.equal(pc.ops[0].method, 'POST');
  assert.equal(pc.ops[0].path, '/programmes');
  assert.deepEqual(pc.ops[0].body, { name: 'Offline Prog' });
  assert.equal(pc.ops[0].token, null);
  assert.ok(pc.timestamp > 0);
});

test('offline PUT queues the op with token', async () => {
  setOnline(false);
  await api.updateUserProfile({ name: 'X' }, 'tok-1');
  const pc = await db.pendingChanges.get('current');
  assert.equal(pc.ops[0].method, 'PUT');
  assert.equal(pc.ops[0].path, '/api/auth');
  assert.equal(pc.ops[0].token, 'tok-1');
});

test('offline DELETE queues the op and returns null', async () => {
  setOnline(false);
  const result = await api.deleteProgramme('abc');
  assert.equal(result, null);
  const pc = await db.pendingChanges.get('current');
  assert.equal(pc.ops[0].method, 'DELETE');
  assert.equal(pc.ops[0].path, '/programmes/abc');
});

test('multiple offline writes accumulate in one batch', async () => {
  setOnline(false);
  await api.createProgramme({ name: 'A' });
  await api.createProgramme({ name: 'B' });
  const pc = await db.pendingChanges.get('current');
  assert.equal(pc.ops.length, 2);
});

// ── api.js: never-queued endpoints ───────────────────────────

test('offline login is not queued and rejects', async () => {
  setOnline(false);
  await assert.rejects(api.authLogin({ email: 'a', password: 'b' }), /Network required/);
  assert.equal(await db.pendingChanges.get('current'), undefined);
});

test('offline face recognition is not queued', async () => {
  setOnline(false);
  await assert.rejects(api.recognizeFaces('p', 'img'), /Network required/);
  assert.equal(await db.pendingChanges.get('current'), undefined);
});

test('offline QR scan is not queued', async () => {
  setOnline(false);
  await assert.rejects(api.lookupByBadge('p', 'badge'), /Network required/);
  assert.equal(await db.pendingChanges.get('current'), undefined);
});

test('online failure on face recognition throws and is not queued', async () => {
  setFetch(() => jsonResponse({ error: 'face server down' }, 500));
  await assert.rejects(api.recognizeFaces('p', 'img'), /face server down/);
  assert.equal(await db.pendingChanges.get('current'), undefined);
});

test('online failure on synced POST is queued for retry', async () => {
  setFetch(() => jsonResponse({ error: 'boom' }, 500));
  const result = await api.createProgramme({ name: 'Retry' });
  assert.deepEqual(result, { name: 'Retry', id: 'pending' });
  const pc = await db.pendingChanges.get('current');
  assert.equal(pc.ops[0].method, 'POST');
});

// ── api.js: headers & success paths ──────────────────────────

test('online request attaches Authorization header when token provided', async () => {
  setFetch(() => jsonResponse({ ok: true }, 200));
  await api.updateUserProfile({ name: 'X' }, 'tok-2');
  assert.equal(fetchCalls[0].init.headers.Authorization, 'Bearer tok-2');
});

test('online write success is returned as-is and not queued', async () => {
  setFetch(() => jsonResponse({ id: 99, name: 'Server Prog' }, 201));
  const result = await api.createProgramme({ name: 'Server Prog' });
  assert.deepEqual(result, { id: 99, name: 'Server Prog' });
  assert.equal(await db.pendingChanges.get('current'), undefined);
});

// ── syncEngine: changeHandler ────────────────────────────────

test('changeHandler is a no-op when there are no pending ops', async () => {
  await changeHandler();
  assert.equal(fetchCalls.length, 0);
});

test('changeHandler posts ops to /sync with auth header and clears queue', async () => {
  authUser({ id: 'u1', token: 'abc' });
  await db.pendingChanges.put({
    id: 'current',
    ops: [{ method: 'POST', path: '/programmes', body: { name: 'X' }, token: null }],
    timestamp: 123,
  });
  let captured = null;
  setFetch((url, init) => {
    captured = { url, init };
    return jsonResponse({ ok: true }, 200);
  });
  await changeHandler();
  assert.equal(captured.url, '/sync');
  assert.equal(captured.init.method, 'POST');
  assert.equal(captured.init.headers.Authorization, 'Bearer abc');
  const sent = JSON.parse(captured.init.body);
  assert.equal(sent.timestamp, 123);
  assert.equal(sent.ops.length, 1);
  assert.deepEqual(sent.ops[0].body, { name: 'X' });
  assert.equal(await db.pendingChanges.get('current'), undefined);
});

test('changeHandler throws on sync failure and keeps pending ops', async () => {
  await db.pendingChanges.put({
    id: 'current',
    ops: [{ method: 'POST', path: '/programmes', body: { name: 'X' }, token: null }],
    timestamp: 1,
  });
  setFetch(() => jsonResponse({ error: 'down' }, 500));
  await assert.rejects(changeHandler(), /Sync failed/);
  const pc = await db.pendingChanges.get('current');
  assert.equal(pc.ops.length, 1);
});

test('changeHandler sends no Authorization when not signed in', async () => {
  await db.pendingChanges.put({
    id: 'current',
    ops: [{ method: 'DELETE', path: '/programmes/1', body: null, token: null }],
    timestamp: 1,
  });
  let captured = null;
  setFetch((url, init) => {
    captured = { url, init };
    return jsonResponse({ ok: true }, 200);
  });
  await changeHandler();
  assert.equal(captured.init.headers.Authorization, undefined);
  assert.equal(await db.pendingChanges.get('current'), undefined);
});

