// Integration tests for the server-side /sync op replay (modules/sync/syncController.js).
// Uses a dedicated throwaway database so the real Sequelize models are exercised.
const { test, before, after } = require('node:test');
const assert = require('node:assert/strict');
const { Client } = require('pg');

process.env.DB_NAME = 'OpenGlimpse_test';
process.env.DB_USER = 'postgres';
process.env.DB_PASSWORD = 'Ray_is_1';
process.env.DB_HOST = 'localhost';
process.env.DB_PORT = '5432';

const {
  sequelize, user, Programme, Route, Delegate,
  AttendanceRecord, ReadyToDepart, ProgrammeDelegate, RouteMember,
} = require('../database/db.cjs');
const { handleSync } = require('../modules/sync/syncController.js');
const dbcrud = require('../database/dbcrudmethods.js');

async function ensureTestDb() {
