let staff, participant, participant2, prog, route, del, del2;

function tokenOf(u) {
  return Buffer.from(`${u.id}:${u.role}`).toString('base64');
}

async function callSync(ops, caller) {
  const out = { status: 200, body: null };
  const req = { body: { ops }, user: caller };
  const res = {
    status(c) { out.status = c; return this; },
    json(b) { out.body = b; },
  };
  await handleSync(req, res);
  return out;
}

