test('non-staff face upload op is allowed and calls embedding methods', async () => {
  const calls = [];
  const origDelete = dbcrud.FaceEmbeddings.deleteByUserIdAndType;
  const origCreate = dbcrud.FaceEmbeddings.createFromImage;
  dbcrud.FaceEmbeddings.deleteByUserIdAndType = async (id, type) => void calls.push(['delete', id, type]);
  dbcrud.FaceEmbeddings.createFromImage = async (id, buf, type) => {
    calls.push(['create', id, buf.toString('base64'), type]);
    return [{}];
  };
  try {
    const res = await callSync(
      [{ method: 'PATCH', path: `/api/user/${participant.id}/face/default`, body: { image: 'aGVsbG8=' }, token: tokenOf(participant) }],
      participant
    );
    assert.equal(res.body.ok, true);
    assert.ok(calls.some((c) => c[0] === 'delete' && c[1] === participant.id && c[2] === 'primary'));
    assert.ok(calls.some((c) => c[0] === 'create' && c[1] === participant.id && c[2] === 'primary' && c[3] === 'aGVsbG8='));
  } finally {
    dbcrud.FaceEmbeddings.deleteByUserIdAndType = origDelete;
    dbcrud.FaceEmbeddings.createFromImage = origCreate;
  }
});

